public boolean remove(int val) {
    int index = (val & 0x7FFFFFFF) % buckets.length;
    Node prev = null;
    Node curr = buckets[index];
    while (curr != null) {
        if (curr.val == val) {
            if (prev == null) {
                buckets[index] = curr.next;
            } else {
                prev.next = curr.next;
            }
            size--;
            return true;
        }
        prev = curr;
        curr = curr.next;
    }
    return false;
}

