private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> content = new HashMap<>();
    if(jsonObject == null){
        return content;
    }
    for(Map.Entry<String, JsonElement> entry : jsonObject.entrySet()){
        String key = entry.getKey();
        JsonElement elem = entry.getValue();
        if(elem == null || elem.isJsonNull()){
            content.put(key, null);
        } else if(elem.isJsonPrimitive()){
            JsonPrimitive prim = elem.getAsJsonPrimitive();
            if(prim.isString()){
                content.put(key, prim.getAsString());
            } else if(prim.isNumber()){
                content.put(key, prim.getAsNumber());
            } else if(prim.isBoolean()){
                content.put(key, prim.getAsBoolean());
            } else {
                content.put(key, prim.getAsString());
            }
        } else if(elem.isJsonArray()){
            content.put(key, elem.getAsJsonArray());
        } else if(elem.isJsonObject()){
            content.put(key, elem.getAsJsonObject());
        } else {
            content.put(key, elem.toString());
        }
    }
    if(jsonObject.has("ats")){
        JsonElement atsElem = jsonObject.get("ats");
        if(atsElem != null && !atsElem.isJsonNull()){
            if(atsElem.isJsonPrimitive()){
                content.put("ats", atsElem.getAsString());
            } else {
                content.put("ats", atsElem.toString());
            }
        }
    }
    return content;
}

